INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818280', 63818280, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'MCB 25A', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 640000, 'January 2026', 'APBD', 1, 1, '4 Buah', 'Kegiatan ini meliputi perencanaan kebutuhan, pengadaan, dan penggantian komponen instalasi listrik guna memastikan seluruh sistem penerangan dan kelistrikan gedung berfungsi secara aman dan berkelanjutan. Selain itu, tugas ini mencakup pemeriksaan berkala terhadap panel listrik serta pengelolaan stok suku cadang untuk mendukung kelancaran operasional dan kenyamanan lingkungan kerja di kantor.', 'Komponen instalasi listrik yang disediakan harus memenuhi standar SNI (Standar Nasional Indonesia) dan memiliki label LMK (Lembaga Masalah Kelistrikan) untuk menjamin keamanan dari risiko arus pendek atau kebakaran. Spesifikasi teknis difokuskan pada penggunaan lampu hemat energi (LED) yang ramah lingkungan serta material kabel dan stop kontak berkualitas tinggi yang memiliki daya tahan beban sesuai dengan kapasitas daya bangunan kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1131810);
