INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818271', 63818271, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Sabun cuci piring 800 ml', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 580000, 'January 2026', 'APBD', 1, 1, '10 Botol', 'Kegiatan ini meliputi penyediaan jasa tenaga pendukung operasional yang profesional untuk memastikan seluruh fungsi pelayanan internal kantor berjalan dengan lancar dan terstruktur. Lingkup pekerjaan mencakup manajemen kebersihan area kerja, pengamanan aset dan personel, layanan transportasi kedinasan, serta dukungan teknis umum lainnya guna menciptakan lingkungan kantor yang kondusif, aman, dan representatif bagi kelancaran tugas harian organisasi.', 'Penyedia jasa wajib menyediakan personel yang memiliki kualifikasi, kompetensi teknis, dan integritas yang sesuai dengan bidang tugasnya masing-masing. Spesifikasi pekerjaan menekankan pada kepatuhan terhadap standar operasional prosedur (SOP) pelayanan, penggunaan seragam dan atribut kerja yang lengkap, pemenuhan hak-hak tenaga kerja sesuai regulasi yang berlaku, serta jaminan kualitas output layanan yang konsisten demi menjaga citra profesionalisme instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1132178);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818226', 63818226, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Biaya pemeliharaan gedung tidak bertingkat', 'Pekerjaan Konstruksi', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 10088000, 'January 2026', 'APBD', 1, 1, '104 Luas / M2', 'Kegiatan ini meliputi pelaksanaan perawatan rutin, perbaikan kerusakan ringan hingga sedang, serta rehabilitasi fisik bangunan guna menjaga keandalan struktur dan fungsi gedung kantor secara berkelanjutan. Lingkup pekerjaan mencakup perbaikan arsitektural, pengecatan ulang, perbaikan sistem sanitasi dan atap yang bocor, serta pemeliharaan area fasad gedung demi memastikan keamanan, kenyamanan, dan keselamatan lingkungan kerja bagi seluruh penghuni bangunan', 'Pekerjaan rehabilitasi harus menggunakan material bangunan yang memenuhi standar SNI dan memiliki kesesuaian estetika dengan desain eksisting guna menjaga keselarasan visual bangunan. Spesifikasi teknis mewajibkan penerapan standar keselamatan kerja yang ketat (K3), penggunaan bahan bangunan yang tahan cuaca (durabilitas tinggi), serta hasil akhir pengerjaan yang rapi dan presisi untuk menjamin integritas struktural bangunan sesuai dengan peraturan teknis bangunan gedung negara yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1132179);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818270', 63818270, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Tisu Besar 250 sheet', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 2200000, 'January 2026', 'APBD', 1, 1, '100 Buah', 'Kegiatan ini meliputi penyediaan jasa tenaga pendukung operasional yang profesional untuk memastikan seluruh fungsi pelayanan internal kantor berjalan dengan lancar dan terstruktur. Lingkup pekerjaan mencakup manajemen kebersihan area kerja, pengamanan aset dan personel, layanan transportasi kedinasan, serta dukungan teknis umum lainnya guna menciptakan lingkungan kantor yang kondusif, aman, dan representatif bagi kelancaran tugas harian organisasi.', 'Penyedia jasa wajib menyediakan personel yang memiliki kualifikasi, kompetensi teknis, dan integritas yang sesuai dengan bidang tugasnya masing-masing. Spesifikasi pekerjaan menekankan pada kepatuhan terhadap standar operasional prosedur (SOP) pelayanan, penggunaan seragam dan atribut kerja yang lengkap, pemenuhan hak-hak tenaga kerja sesuai regulasi yang berlaku, serta jaminan kualitas output layanan yang konsisten demi menjaga citra profesionalisme instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1132180);
