INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818273', 63818273, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Pembersih Kamar Mandi', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 980000, 'January 2026', 'APBD', 1, 1, '20 Buah', 'Kegiatan ini meliputi penyediaan jasa tenaga pendukung operasional yang profesional untuk memastikan seluruh fungsi pelayanan internal kantor berjalan dengan lancar dan terstruktur. Lingkup pekerjaan mencakup manajemen kebersihan area kerja, pengamanan aset dan personel, layanan transportasi kedinasan, serta dukungan teknis umum lainnya guna menciptakan lingkungan kantor yang kondusif, aman, dan representatif bagi kelancaran tugas harian organisasi.', 'Penyedia jasa wajib menyediakan personel yang memiliki kualifikasi, kompetensi teknis, dan integritas yang sesuai dengan bidang tugasnya masing-masing. Spesifikasi pekerjaan menekankan pada kepatuhan terhadap standar operasional prosedur (SOP) pelayanan, penggunaan seragam dan atribut kerja yang lengkap, pemenuhan hak-hak tenaga kerja sesuai regulasi yang berlaku, serta jaminan kualitas output layanan yang konsisten demi menjaga citra profesionalisme instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1133809);
