INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63818240', 63818240, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Tagihan Listrik', 'Jasa Lainnya', 'Dikecualikan', 'DI Yogyakarta, Sleman (Kab.)', 12000000, 'January 2026', 'APBD', 1, 1, '4 Triwulan', 'Kegiatan ini meliputi pengelolaan dan pemenuhan kewajiban pembayaran tagihan rutin serta pemeliharaan konektivitas layanan vital guna menjamin keberlangsungan operasional kantor sehari-hari. Lingkup pekerjaan mencakup pemantauan konsumsi daya listrik, ketersediaan air bersih, dan stabilitas jaringan komunikasi, serta melakukan koordinasi dengan penyedia jasa layanan publik terkait untuk memastikan tidak adanya hambatan teknis yang dapat mengganggu pelayanan kedinasan.', 'Layanan yang disediakan harus memenuhi standar keandalan tinggi dengan tingkat gangguan minimal guna mendukung infrastruktur digital dan sanitasi gedung yang optimal. Spesifikasi teknis mencakup ketersediaan daya listrik yang stabil sesuai kapasitas bangunan, pasokan air bersih yang memenuhi standar kesehatan, serta koneksi internet dan saluran komunikasi dengan bandwidth yang memadai serta rasio ketersediaan (uptime) yang menjamin kelancaran pertukaran data dan informasi instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1134919);
