INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63758588', 63758588, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Penyebaran Siaran Pers', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan Penyebaran Siaran Pers dilaksanakan sepanjang tahun 2026 oleh Biro Humas Kementerian Ketenagakerjaan sebagai bagian dari dukungan komunikasi publik institusi. Kegiatan ini meliputi proses pendistribusian siaran pers resmi Kementerian Ketenagakerjaan kepada media massa, pemangku kepentingan, dan jaringan komunikasi terkait melalui surat elektronik (email) secara terjadwal, cepat, dan akuntabel, dengan memanfaatkan aplikasi bantu yang dirancang khusus untuk mendukung pengelolaan basis data penerima, otomasi pengiriman, serta pencatatan status distribusi. Pelaksanaan pekerjaan memastikan setiap siaran pers tersampaikan secara tepat sasaran, konsisten, dan terdokumentasi dengan baik sebagai bahan monitoring, evaluasi, dan arsip komunikasi publik, guna mendukung transparansi kebijakan, peningkatan jangkauan informasi, serta penguatan citra dan kredibilitas Kementerian Ketenagakerjaan di ruang publik.', 'Pekerjaan Penyebaran Siaran Pers merupakan kegiatan pendukung komunikasi publik Kementerian Ketenagakerjaan yang dilaksanakan sepanjang tahun 2026. Lingkup pekerjaan mencakup pengelolaan, pengiriman, dan pendokumentasian distribusi siaran pers resmi Kemnaker kepada media massa dan pemangku kepentingan melalui email dengan memanfaatkan aplikasi bantu yang telah disediakan. Penyedia jasa bertanggung jawab memastikan proses pengiriman dilakukan secara tepat waktu, terjadwal, dan sesuai daftar distribusi yang ditetapkan, termasuk pengelolaan basis data alamat email media, pengoperasian aplikasi pengiriman massal (email blast), serta pemantauan status pengiriman (terkirim, gagal, atau tertunda). Selain itu, pekerjaan meliputi penyusunan laporan distribusi siaran pers secara berkala sebagai bahan monitoring dan evaluasi kinerja komunikasi publik, serta memastikan seluruh proses terdokumentasi dengan baik untuk kepentingan arsip dan akuntabilitas pelaksanaan kegiatan.', 25000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1139946);
